#include "StdAfx.h"#include "ClientConnection.h"//#ifdef LINUX#include "LogFile.h"//#endif // LINUXKClientConnection::KClientConnection( SOCKET Sock, bool bMainPipe ): m_Socket( Sock ), m_bMainPipe (bMainPipe){	//InitializeCriticalSection (&c_cCritSect);}KClientConnection::~KClientConnection(void){}BOOL KClientConnection::ReadData( PVOID lpBuffer, DWORD nNumberOfBytesToRead, LPDWORD lpNumberOfBytesRead ){	if( lpNumberOfBytesRead )		*lpNumberOfBytesRead = 0;#ifdef NEW_LOGIC	//EnterCriticalSection (&c_cCritSect);	CLogFile::LogEx (LOGLEVEL_HIGH, "KClientConnection::ReadData_0: nNumberOfBytesToRead = %d", nNumberOfBytesToRead);	BYTE *pPtr = (BYTE *)lpBuffer;	int nTotalRead = 0, nCurSize = min (RCV_BUFSIZE, (int)nNumberOfBytesToRead);	while ( nTotalRead < (int)nNumberOfBytesToRead )	{		int nCurRead = recv( m_Socket, (char *)(pPtr + nTotalRead), nCurSize, 0 );		if ( SOCKET_ERROR == nCurRead )		{			int nError = WSAGetLastError();			CLogFile::LogEx (LOGLEVEL_HIGH, "KClientConnection::ReadData: FAILURE 1: nError %d", nError);			//LeaveCriticalSection (&c_cCritSect);			return false;		}		if ( nCurSize != nCurRead )		{			CLogFile::LogEx (LOGLEVEL_HIGH, "KClientConnection::ReadData: FAILURE 2: nCurRead: %d, nCurSize %d", nCurRead, nCurSize);			//if( lpNumberOfBytesRead )				//*lpNumberOfBytesRead += nCurRead;			//return false;		}		nTotalRead += nCurRead;		CLogFile::LogEx (LOGLEVEL_HIGH, "KClientConnection::ReadData_3: nCurRead: %d, nTotalRead %d", nCurRead, nTotalRead);		if( lpNumberOfBytesRead )			*lpNumberOfBytesRead += nCurRead;		int nReminder = ((int)nNumberOfBytesToRead - nTotalRead);		nCurSize = min (RCV_BUFSIZE, nReminder);	}	CLogFile::LogEx (LOGLEVEL_HIGH, "KClientConnection::ReadData_4 SUCCESS: nTotalRead %d", nTotalRead);	if( lpNumberOfBytesRead )		*lpNumberOfBytesRead = (DWORD)nTotalRead;	//LeaveCriticalSection (&c_cCritSect);#else  char *pBuf = (char*)lpBuffer;  int leftData = nNumberOfBytesToRead;  while( leftData )  {    int r = recv( m_Socket, pBuf, leftData, 0 );    if( SOCKET_ERROR==r )    {      int err = WSAGetLastError();      return FALSE;    }    if( 0==r )    {      int err = WSAGetLastError();      if( 0==err )        return FALSE;      return FALSE;    }    if( lpNumberOfBytesRead )      *lpNumberOfBytesRead += r;    pBuf += r;    leftData -= r;  }#endif // NEW_LOGIC  return TRUE;}BOOL KClientConnection::WriteData( LPCVOID lpBuffer, DWORD nNumberOfBytesToWrite, LPDWORD lpNumberOfBytesWritten ){#ifdef NEW_LOGIC	BYTE *pPtr = (BYTE *)lpBuffer;	int nTotalWritten = 0, nCurSize = min (SND_BUFSIZE, (DWORD)nNumberOfBytesToWrite);	while ( nTotalWritten < (int)nNumberOfBytesToWrite )	{		int nCurWritten = send( m_Socket, (char*)(pPtr + nTotalWritten), nCurSize, 0 );		if ( SOCKET_ERROR == nCurWritten )		{			int nError = WSAGetLastError();			CLogFile::LogEx (LOGLEVEL_HIGH, "KClientConnection::WriteData FAILURE: nCurSize %d, nNumberOfBytesToWrite %d, nError %d", nCurSize, nNumberOfBytesToWrite, nError);			return FALSE;		}		nTotalWritten += nCurWritten;		int nReminder = ((int)nNumberOfBytesToWrite - nTotalWritten);		nCurSize = min (SND_BUFSIZE, nReminder);	}	if( lpNumberOfBytesWritten )		*lpNumberOfBytesWritten = (DWORD)nTotalWritten;		CLogFile::LogEx (LOGLEVEL_HIGH, "KClientConnection::WriteData OK: nTotalWritten %d, nNumberOfBytesToWrite %d", nTotalWritten, nNumberOfBytesToWrite);	return TRUE;#else  int s = send( m_Socket, (char*)lpBuffer, nNumberOfBytesToWrite, 0 );  if( SOCKET_ERROR==s )    return FALSE;  ASSD( s==nNumberOfBytesToWrite );  if( lpNumberOfBytesWritten )    *lpNumberOfBytesWritten = s;  return TRUE;#endif // NEW_LOGIC}